WFJ.Data.add("gossip", {
  ["02019693e71428d0"] = { "Notevole, davvero notevole. Sa fare qualche giochetto?", "." },
  ["0208d0b3facd0298"] = { "Quante probabilità ci sono di ottenere una pelle del genere?", "." },
  ["020c103273c112cf"] = { "Prendi uno sgabello e fatti un goccio!", "." },
  ["020d753295d6e4b6"] = { "Raccogli i tuberi dalla sferzarapa.", "." },
  ["021b67272d62e0f2"] = { "Scagnozzi? Tributi?", "." },
  ["021e8a7e5eee4e6c"] = { "Gli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧ si trovano all'estremità nord della ⟦Zoram Strand=Spiaggia di Zoram⟧, lungo la costa di ⟦Ashenvale=Valtetra⟧.", "." },
  ["0220a8508f9c0e90"] = { "Stringetevi attorno ai vostri luogotenenti e comandanti! Proteggete le nostre basi!", "." },
  ["022aa864abcf853a"] = { "Non cercare di imporre la tua volontà al cuoio. Lascia piuttosto che siano le sue tendenze naturali a stabilire la forma e la funzione che assumerà. Non è una battaglia da vincere. Lavora con il cuoio, non contro di esso.", "." },
  ["023be434f81f9fe8"] = { "Marion Call tiene compagnia al chierico oscuro Beryl nella sala di lettura al piano di sopra della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, sul margine sud-est di Brill. Muoio dalla voglia di vedere chi vince quella gara di sguardi.", "." },
  ["023c23543cad7359"] = { "Fatevi avanti e sentite parlare dello spettacolo più straordinario di tutta Azeroth: la ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Urrà!", "." },
  ["023cce0431f06786"] = { "Aiutami a schiacciare questi mingherlini!", "." },
  ["0241fb4bd5797de1"] = { "Inserimento della tessera di sicurezza blu riuscito. Erogazione dell'unità di livello di sicurezza delta.\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111", "." },
  ["02468fc4bdad69ed"] = { "Una volta ho avuto il piacere di vedere Kyra Windblade in combattimento. Per quello che ho visto, confido che ti addestrerà bene. Cercala alla locanda di Dolanaar.", "." },
  ["02471978065578e2"] = { "Va bene, ragazzi. Indietro. Avete fatto abbastanza. Ci vediamo più tardi.", "." },
  ["024ea4f34b8524b5"] = { "Lingotti d'oro, sì... sì. Portamene uno e vedremo cosa si può fare per filarti un po' di filo. Nel frattempo, ti suggerirei di concentrare i tuoi sforzi sul diventare più potente. Le prove più dure ti aspettano ancora. E fidati... vorrai essere più preparat<o/a>, per quanto potente tu creda di essere.", "." },
  ["025a46a134a43431"] = { "Ho degli appunti sul lavoro a casa mia. Vado a prenderli e poi ci rivediamo alla locanda.", "." },
  ["026274b143fddf99"] = { "Vuoi lavorare alla forgia? Vuoi forgiare lame per sventrare il tuo nemico? Martelli per spaccargli il cranio? Sì, posso aiutarti, e volentieri, se c'è sangue da versare.", "." },
  ["026854b81d10815b"] = { "%s cerca una fonte di energia arcana.", "." },
  ["026891decbe6adab"] = { "%s emette uno strillo assordante!", "." },
  ["026d7343787cecce"] = { "Dov'è l'anziano Meadowrun?", "." },
  ["0271fc98d0e5f7bb"] = { "Ora lo mescolo con cura... ops! ...Beh, ne ho versato un po', ma è pronto!", "." },
  ["0273818d25335f96"] = { "%s inizia a sbattere le ali all'impazzata e a strillare forte. Hai la sensazione di essere il suo prossimo pasto.", "." },
  ["027768764c0ca540"] = { "Proteggere padrone!", "." },
  ["027ea04bfc86606e"] = { "Le vostre anime malvagie nutriranno il mio potere!", "." },
  ["027f068ec4db3233"] = { "L'arte sartoriale degli Shen'dorei è un'imitazione armoniosa delle correnti fluide e spensierate dei venti. Anche se gli spiriti ci hanno lasciati, e non so quando li vedrò danzare di nuovo... trovo grande conforto nella mia arte, se non altro come distrazione.\n\nPosso insegnarti anche a lavorare la stoffa, se vuoi imparare.", "." },
  ["028ecfe5c5c3236e"] = { "Non posso addestrarti, {class}.", "." },
  ["028f7ec9d0322b67"] = { "Nessuno è abile nell'uso delle armi quanto Ansekhwa. Si dice che sia guidato dagli spiriti dei più grandi guerrieri dei nostri onorati antenati. Cercalo sull'altura inferiore e ti insegnerà ciò che vuoi sapere.", "." },
  ["029197863f600c5e"] = { "Premi misteriosi attendono gli avventurosi. Avvicinatevi, avvicinatevi!", "." },
  ["0293f4713ea5280d"] = { "Tiratelo fuori di lì!", "." },
  ["0295528a8cacb170"] = { "Sono Jin'rokh il Distruttore, inviato di Mugamba, Pugno di Rastakhan!\n\nTratto solo con guerrieri e infedeli.", "." },
  ["02a5401a3e74210b"] = { "Padroneggio l'arte del fabbro, Omarion.", "." },
  ["02a9b8b4ced538a5"] = { "Lassù Lorthuna sta compiendo una specie di rituale. Forse cerca di abbattere le protezioni!\n\nI rinforzi che abbiamo chiesto non sono ancora arrivati, ma dovremo arrangiarci con quello che abbiamo. Quando sei <pronto/pronta>, fammelo sapere e andremo ad affrontarla.", "." },
  ["02ae2aa1d6c0eab1"] = { "La mia redenzione? Hai del fegato, piccola creatura. La mia redenzione arriva per volontà del mio dio.", "." },
  ["02af82d14e327b1f"] = { "Il magistrato è caduto! Fuggite, fratelli miei.", "." },
  ["02b24c682f325635"] = { "Molto bene. La nostra scorta di provviste cresce...", "." },
  ["02b370e1ee8d382b"] = { "Questo è il braciere, {name}. Spegnilo. Vorsha è una bestia che non merita la lode di nessuno!", "." },
  ["02bb8d85133be291"] = { "Fammi vedere cosa sai fare! Non te ne pentirai, te lo prometto!", "." },
  ["02bd5e4826183079"] = { "Al tuo avvicinarti, liquidi e miscugli gorgogliano e sussultano. Accanto all'attrezzatura c'è un grosso paio di pinze che sembrerebbero adatte a calare campioni di melma.\n\nC'è anche dell'equipaggiamento di sicurezza, ma sembra impolverato e trascurato da tempo.\n\nPensi che toccare qualcosa non sarebbe saggio.", "." },
  ["02c5b17f1c157085"] = { "Ora inchinati a me.", "." },
  ["02c8a3816d0460ff"] = { "Non preoccuparti, Vecchio Blanchy, presto ti troveremo qualcosa da mangiare...", "." },
  ["02e38e54ab2679e2"] = { "Se sei qui per altro addestramento, hai sopravvalutato le mie capacità. Parla con Telonis, laggiù: lui può aiutarti.", "." },
  ["02e45a7f7b862eea"] = { "Salute, {name}. Sono Myolor Sunderfury, custode della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["02e6ee4123368d63"] = { "Chi osa disturbare il mio riposo eterno? Le vostre morti saranno lente e dolorose!", "." },
  ["02e9b6ffb90c8472"] = { "Billy dice che Fizzles una volta era un grande mago. Ma è stato trasformato in un coniglio quando uno dei suoi incantesimi è andato storto.", "." },
  ["02f5493ab1dfd020"] = { "Oltre questo corridoio, Naralex giace in un sonno agitato. Andiamo a svegliarlo prima che sia troppo tardi.", "." },
  ["02f6ec5f492c3398"] = { "È l'ora della tua ultima resistenza, insetto.", "." },
})
